(function(){
'use strict';
const DATA_URL='team-results-2026.json?v=20260718-v1';
let dataPromise=null;
function norm(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9]/g,'').toUpperCase()}
function esc(value){return String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function ensureStyles(){if(document.getElementById('cff-team-results-2026-css'))return;const style=document.createElement('style');style.id='cff-team-results-2026-css';style.textContent=`
.cff-team-results-2026{width:100%;margin:0 0 30px;text-align:left}.cff-team-results-2026>h2{margin:0 0 14px;color:#fff;font-size:1.08rem;text-transform:uppercase;letter-spacing:.06em}.cff-team-results-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:14px}.cff-team-results-card{overflow:hidden;border:1px solid rgba(0,200,255,.16);border-radius:16px;background:rgba(8,17,37,.74)}.cff-team-results-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 15px;border-bottom:1px solid rgba(255,255,255,.07);background:linear-gradient(90deg,rgba(0,200,255,.08),transparent)}.cff-team-results-head strong{color:#fff;font-size:.92rem}.cff-team-results-head span{color:#7dcfff;font-size:.7rem;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.cff-team-results-stage{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:12px 15px;border-bottom:1px solid rgba(255,255,255,.055)}.cff-team-results-stage:last-child{border-bottom:0}.cff-team-results-stage-main{min-width:0}.cff-team-results-stage-main b{display:block;color:#edf8ff;font-size:.86rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cff-team-results-stage-main small{display:block;margin-top:4px;color:#8ea7bf;font-size:.75rem;font-weight:700}.cff-team-results-position{min-width:58px;text-align:center;border-radius:12px;padding:8px 9px;background:rgba(0,200,255,.07);border:1px solid rgba(0,200,255,.14);color:#20cbff;font-size:1rem;font-weight:950}.cff-team-results-stage.is-champion .cff-team-results-position{color:#ffd927;border-color:rgba(255,217,39,.3);background:rgba(255,217,39,.08)}.cff-team-results-stage.is-champion .cff-team-results-stage-main b{color:#ffd927}.cff-team-results-empty{padding:14px;border:1px solid rgba(255,255,255,.08);border-radius:14px;color:#8ea7bf;text-align:center}.cff-team-results-loading{padding:16px;color:#8ea7bf;text-align:center}
@media(max-width:640px){.cff-team-results-grid{grid-template-columns:1fr}.cff-team-results-stage{padding:11px 12px}.cff-team-results-stage-main b{font-size:.8rem}.cff-team-results-stage-main small{font-size:.69rem}.cff-team-results-position{min-width:50px;font-size:.9rem}}
`;document.head.appendChild(style)}
async function loadData(){if(!dataPromise)dataPromise=fetch(DATA_URL,{cache:'default'}).then(r=>{if(!r.ok)throw new Error('Falha ao carregar resultados das equipes');return r.json()}).catch(error=>{dataPromise=null;throw error});return dataPromise}
function findTeam(payload,name){const wanted=norm(name);return(payload?.teams||[]).find(team=>norm(team.canonical)===wanted||(team.aliases||[]).some(alias=>norm(alias)===wanted))||null}
function stageStatus(stage){if(stage.champion)return'CAMPEÃO';return String(stage.status||'').trim()}
function tournamentCard(tournament){return`<article class="cff-team-results-card"><header class="cff-team-results-head"><strong>${esc(tournament.name)}</strong><span>RESULTADOS</span></header>${(tournament.stages||[]).map(stage=>`<div class="cff-team-results-stage${stage.champion?' is-champion':''}"><div class="cff-team-results-stage-main"><b>${stage.champion?'🏆 ':''}${esc(stage.label)}</b><small>${Number(stage.points)||0} pts • ${Number(stage.booyahs)||0} B! • ${Number(stage.kills)||0} K • ${Number(stage.matches)||0} Q${stageStatus(stage)?` • ${esc(stageStatus(stage))}`:''}</small></div><div class="cff-team-results-position">${Number(stage.position)||'—'}º</div></div>`).join('')}</article>`}
async function buildHtml(teamName,options){ensureStyles();const payload=await loadData();const team=findTeam(payload,teamName);if(!team||!team.tournaments?.length)return'';const allowed=options?.tournaments&&Array.isArray(options.tournaments)?new Set(options.tournaments):null;const tournaments=team.tournaments.filter(t=>!allowed||allowed.has(t.id));if(!tournaments.length)return'';return`<section class="cff-team-results-2026"><h2>Resultados em 2026</h2><div class="cff-team-results-grid">${tournaments.map(tournamentCard).join('')}</div></section>`}
async function renderStandardTeamProfile(teamName){const profile=document.getElementById('team-profile');if(!profile)return;ensureStyles();let mount=document.getElementById('tp-results-2026-mount');if(!mount){mount=document.createElement('div');mount.id='tp-results-2026-mount';const anchor=document.getElementById('tp-next-match-container');if(anchor)anchor.insertAdjacentElement('afterend',mount);else profile.querySelector('.profile-header')?.insertAdjacentElement('afterend',mount)}if(!mount)return;mount.innerHTML='<div class="cff-team-results-loading">Carregando resultados...</div>';try{const html=await buildHtml(teamName);mount.innerHTML=html;if(html){const oldSummary=document.getElementById('tp-final-summary');if(oldSummary)oldSummary.style.display='none'}}catch(error){console.error('[Resultados 2026]',error);mount.innerHTML=''}}
function wrapOpenTeamProfile(){const original=window.openTeamProfile;if(typeof original!=='function'||original.__cffResults2026Wrapped)return;async function wrapped(){const result=await original.apply(this,arguments);const shown=document.getElementById('tp-name')?.textContent?.trim()||arguments[0];renderStandardTeamProfile(shown);return result}wrapped.__cffResults2026Wrapped=true;wrapped.__cffOriginal=original;window.openTeamProfile=wrapped}
window.cffGetTeamResults2026=loadData;
window.cffBuildTeamResults2026HTML=buildHtml;
window.cffRenderStandardTeamResults2026=renderStandardTeamProfile;
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',wrapOpenTeamProfile,{once:true});else wrapOpenTeamProfile();
})();
